const PRE = (typeof window !== 'undefined' && window.__PRELOAD__) || null;

/* ── 城市表 ── */
async function loadCities(){
  if (PRE && PRE.cities){
    CITIES = PRE.cities;
    $('city').innerHTML = CITIES.map(c => `<option value="${c.name}">${c.name}</option>`).join('');
    $('city').value = (PRE.fact && PRE.fact.input.city) || CITIES[0].name;
    if (PRE.fact){
      const i = PRE.fact.input;
      $('y').value = i.y; $('m').value = i.m; $('d').value = i.d;
      $('h').value = i.h; $('mi').value = i.mi;
      $('gender').value = i.gender; $('basis').value = i.basis;
    }
    updateHint();
    return;
  }
  const r = await fetch('/api/cities');
  CITIES = (await r.json()).cities;
  $('city').innerHTML = CITIES.map(c => `<option value="${c.name}">${c.name}</option>`).join('');
  $('city').value = '北京';
  updateHint();
}
function updateHint(){
  const c = CITIES.find(x => x.name === $('city').value);
  if(!c) return;
  const lonMin = (c.lon - 120) * 4;
  $('cityHint').textContent =
    `${c.name}：东经 ${c.lon}°　北纬 ${c.lat}°　→　经度时差 ${lonMin >= 0 ? '+' : ''}${lonMin.toFixed(1)} 分钟`
    + (Math.abs(lonMin) > 30 ? '（偏离标准经线较远，真太阳时校正影响显著）' : '');
}
$('city').addEventListener('change', updateHint);

/* ── 起盘 ── */
async function go(){
  const btn = $('go'); btn.disabled = true; btn.textContent = '推演中…';
  $('err').classList.remove('show');
  if (PRE && PRE.fact){ LAST = PRE.fact; render(PRE.fact); btn.disabled = false; btn.textContent = '起　盘'; return; }
  $('out').innerHTML = '<div class="loading">正在排盘…</div>';
  try{
    const body = {
      y:+$('y').value, m:+$('m').value, d:+$('d').value, h:+$('h').value, mi:+$('mi').value,
      gender:$('gender').value, city:$('city').value, basis:$('basis').value,
    };
    const r = await fetch('/api/chart', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)});
    const j = await r.json();
    if(!r.ok) throw new Error((j.details || [j.error]).join('；'));
    LAST = j;
    render(j);
  }catch(e){
    $('err').textContent = '排盘失败：' + e.message;
    $('err').classList.add('show');
    $('out').innerHTML = '<div class="empty">请修正输入后重试</div>';
  }finally{
    btn.disabled = false; btn.textContent = '起　盘';
  }
}
$('go').addEventListener('click', go);
$('demo').addEventListener('click', () => {
  const y = 1955 + Math.floor(Math.random()*60);
  const m = 1 + Math.floor(Math.random()*12);
  const d = 1 + Math.floor(Math.random()*28);
  const h = Math.floor(Math.random()*24);
  const mi = Math.floor(Math.random()*60);
  const c = CITIES[Math.floor(Math.random()*CITIES.length)];
  $('y').value = y; $('m').value = m; $('d').value = d; $('h').value = h; $('mi').value = mi;
  if(c) { $('city').value = c.name; updateHint(); }
  $('gender').value = Math.random() < .5 ? '男' : '女';
  go();
});

