/** 输入校验：宁可明确报错，也不要用默认值悄悄算出一张错的盘 */
function validate(input) {
  const errs = [];
  const num = (v, name, min, max) => {
    const n = Number(v);
    if (!Number.isFinite(n)) { errs.push(`${name} 必须是数字`); return null; }
    if (n < min || n > max) { errs.push(`${name} 应在 ${min}–${max} 之间，收到 ${n}`); return null; }
    return n;
  };

  const y = num(input.y, '出生年', 1901, 2099);
  const m = num(input.m, '出生月', 1, 12);
  const d = num(input.d, '出生日', 1, 31);
  const h = num(input.h, '出生时', 0, 23);
  const mi = num(input.mi ?? 0, '出生分', 0, 59);

  if (input.gender && !['男', '女'].includes(input.gender)) errs.push('性别须为「男」或「女」');

  // 日期真实性检查（2月30日之类）
  if (y && m && d) {
    const dt = new Date(Date.UTC(y, m - 1, d));
    if (dt.getUTCMonth() + 1 !== m || dt.getUTCDate() !== d) errs.push(`${y}年${m}月没有${d}日`);
  }

  let lon = input.lonEast, lat = input.lat;
  if (input.city) {
    const c = BY_NAME[input.city];
    if (c) { lon = c.lon; lat = c.lat; }
    else errs.push(`未收录城市「${input.city}」，请改用经纬度输入`);
  }
  if (lon == null || lat == null) {
    errs.push('需要提供城市，或直接给出经纬度（lonEast / lat）');
  } else {
    const LON = num(lon, '经度', -180, 180);
    const LAT = num(lat, '纬度', -66, 66);
    lon = LON; lat = LAT;
  }

  if (input.basis && !['solar', 'clock'].includes(input.basis)) errs.push('时间基准须为 solar 或 clock');

  return {
    errors: errs,
    value: { y, m, d, h, mi, gender: input.gender || '男', city: input.city || null, lonEast: lon, lat, basis: input.basis },
  };
}

